INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Can I bulk download an entire creator page?', 'You can bulk download all visible posts on the current creator page. The extension collects up to 60 visible post IDs at a time, then provides a Download Visible action within each tab.', 2);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Do I get quality options?', 'No quality picker is necessary for Coomer. The downloader saves files in the original quality exposed by the API, so videos and images download exactly as the source provides them without any transcoding.', 3);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Where are my downloads saved?', 'Files go automatically into a Coomer Downloader folder in your browser''s default Downloads directory, organized by creator and prefixed with the published date when that information is available.', 4);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Which Coomer domains are supported?', 'The extension covers Coomer.su as the primary domain, along with Coomer.st and Coomer.party legacy domains.', 5);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Can it download private or inaccessible content?', 'No. The extension only works with content that is already accessible from the current page. It does not bypass access controls, DRM, or any permissions you do not have.', 6);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Which browsers are supported?', 'Compatible desktop builds cover Chrome, Edge, Firefox, Brave, Opera, Whale, and Yandex on Windows, macOS, and Linux. Safari and mobile browsers are not supported.', 7);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Is there a free trial?', 'Yes. After email verification, you receive 3 trial downloads for free. Once those are used, unlimited downloads are available through the paid subscription.', 8);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Is my data private?', 'Yes. Scanning, extraction, text generation, and all downloads run locally inside your browser. Authentication uses secure OTP email verification, and no media files are uploaded to external servers.', 9);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_52395670bf936723959d5f29', 'Is this legal?', 'DISCLAIMER: We are not attorneys and do not offer legal advice. Laws vary by country and platform. For any legal question please consult a qualified legal professional.

