INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_7d85d9080c9469cc025afdb5', 'What happens if the stream temporarily drops?', 'The heartbeat monitor detects the interruption. When the stream resumes, recording continues automatically and the final file is stitched into a single continuous MP4.', 3);
INSERT INTO listing_faqs (listing_id, question, answer, sort_order) VALUES ('lst_7d85d9080c9469cc025afdb5', 'How much disk space do recordings use?', 'A typical one-hour cam session at 720p uses roughly 1 to 3 GB depending on bitrate. Higher resolutions consume proportionally more space.', 4);
